150:     fn card_dims(&self, inner_w: f32) -> (f32, f32, f32) {
151:         let gap = 16.0;
152:         let cols = self.cols as f32;
153:         let cw = ((inner_w - gap * (cols - 1.0)) / cols).floor();
154:         let mh = (cw * 10.0 / 16.0).round().max(120.0);
155:         (cw, mh, mh + 48.0 + gap)
156:     }
