167:     fn layout_rows(&self, inner_w: f32) -> (Vec<(Row, f32, f32)>, f32) {
168:         let grid = self.st().grid;
169:         let (_, _, pitch) = self.card_dims(inner_w);
170:         let (_, mh, _) = self.card_dims(inner_w);
171:         let mut rows = vec![];
172:         let mut y = if grid { 92.0 } else { 118.0 };
173:         if !grid {
174:             rows.push((Row::FieldHeader, 84.0, 28.0));
175:         }
176:         for (si, s) in self.sections.iter().enumerate() {
177:             rows.push((Row::Header(si), y, 24.0));
178:             y += 26.0;
179:             if grid {
180:                 let mut i = s.start;
181:                 while i < s.end {
182:                     let e = (i + self.cols).min(s.end);
183:                     let h = if s.folders { 70.0 + 16.0 } else { pitch };
184:                     rows.push((Row::Cards(i, e, s.folders), y, h));
185:                     y += h;
186:                     i = e;
187:                 }
188:                 y += 26.0;
189:             } else {
190:                 let mut i = s.start;
191:                 while i < s.end {
192:                     rows.push((Row::Cards(i, i + 1, s.folders), y, 42.0));
193:                     y += 42.0;
194:                     i += 1;
195:                 }
196:                 y += 18.0;
197:             }
198:         }
199:         let _ = mh;
200:         (rows, y + 26.0)
201:     }
