423:     fn draw_items(&mut self, ui: &mut Ui, o: Pos2, w: f32, inner_w: f32, vp: Rect) {
424:         ITEM_RECTS.with(|v| v.borrow_mut().clear());
425:         let p = ui.painter().clone();
426:         if self.items.is_empty() {
427:             self.draw_empty(ui, o, w);
428:             return;
429:         }
430:         let grid = self.st().grid;
431:         let (rows, _) = self.layout_rows(inner_w);
432:         let (cw, mh, _) = self.card_dims(inner_w);
433:         let cols = self.cols_for(o, w);
434:         for (row, y, h) in rows {
435:             if y + h.max(24.0) < vp.top() - 60.0 || y > vp.bottom() + 60.0 {
436:                 continue;
437:             }
438:             match row {
439:                 Row::FieldHeader => self.draw_list_head(ui, o, w, cols),
440:                 Row::Header(si) => {
441:                     let (title, n) = (self.sections[si].title.clone(), self.sections[si].end - self.sections[si].start);
442:                     self.section_label(&p, o, y, w, &title, n);
443:                 }
444:                 Row::Cards(a, b, folders) => {
445:                     for i in a..b {
446:                         if grid {
447:                             let col = i - a;
448:                             let x = o.x + PAD_X + col as f32 * (cw + 16.0);
449:                             if folders {
450:                                 let r = Rect::from_min_size(pos2(x, o.y + y), vec2(cw, 70.0));
451:                                 self.folder_card(ui, i, r);
452:                             } else {
453:                                 let r = Rect::from_min_size(pos2(x, o.y + y), vec2(cw, mh + 48.0));
454:                                 self.file_card(ui, i, r, mh);
455:                             }
456:                         } else {
457:                             let r = Rect::from_min_size(pos2(o.x + PAD_X - 10.0, o.y + y), vec2(w - 2.0 * PAD_X + 20.0, 42.0));
458:                             self.list_row(ui, i, r, cols);
459:                         }
460:                     }
461:                 }
462:             }
463:         }
464:     }
