466:     fn item_interaction(&mut self, ui: &Ui, i: usize, hit: Rect, e: &Entry) -> egui::Response {
467:         let resp = ui.interact(hit, Id::unique(("item", &e.loc)), Sense::click_and_drag());
468:         ITEM_RECTS.with(|v| v.borrow_mut().push((e.loc.clone(), hit)));
469:         // Selection model: a plain click only *focuses* (soft highlight). Ticks, long-press, Ctrl/Shift-click, marquee
470:         // and Select All enter selection mode, where a plain click toggles.
471:         let long = resp.long_touched();
472:         if long || resp.clicked() {
473:             let m = ui.input(|i| i.modifiers);
474:             let multi_key = m.command || m.ctrl;
475:             if long {
476:                 self.toggle_tick(&e.loc);
477:                 self.anchor = Some(i);
478:             } else if m.shift && self.anchor.is_some() {
479:                 let a = self.anchor.unwrap();
480:                 let (lo, hi) = (a.min(i), a.max(i));
481:                 self.sel = self.items[lo..=hi].iter().map(|e| e.loc.clone()).collect();
482:                 self.select_mode = true;
483:             } else if multi_key || self.select_mode {
484:                 self.toggle_tick(&e.loc);
485:                 self.anchor = Some(i);
486:             } else {
487:                 self.sel.clear();
488:                 self.sel.insert(e.loc.clone());
489:                 self.anchor = Some(i);
490:             }
491:             self.focus = Some(i);
492:         }
493:         if resp.double_clicked() {
494:             self.acts.push(Act::Open(e.loc.clone()));
495:         }
496:         if resp.secondary_clicked() {
497:             if !self.sel.contains(&e.loc) {
498:                 self.sel.clear();
499:                 self.sel.insert(e.loc.clone());
500:             }
501:             self.menu = Some(Menu { kind: MenuKind::Item, pos: ui.ctx().pointer_latest_pos().unwrap_or(hit.center()), target: Some(e.loc.clone()), device: None, sub: None, age: 0.0 });
502:         }
503:         if resp.drag_started() {
504:             if !self.sel.contains(&e.loc) {
505:                 self.sel.clear();
506:                 self.sel.insert(e.loc.clone());
507:             }
508:             let items: Vec<Location> = self.selected().iter().map(|x| x.loc.clone()).collect();
509:             let label = if items.len() == 1 { e.name.clone() } else { format!("{} items", items.len()) };
510:             let frozen_dest = self.target_dir();
511:             self.drag = Some(Drag { items, label, frozen_dest });
512:         }
513:         resp
514:     }
