516:     fn name_or_rename(&mut self, ui: &mut Ui, e: &Entry, pos: Pos2, max_w: f32, font: egui::FontId, col: Color32) -> f32 {
517:         let p = ui.painter().clone();
518:         if self.rename.as_ref().is_some_and(|r| r.loc == e.loc) {
519:             let rr = Rect::from_min_size(pos + vec2(-4.0, -11.0), vec2(max_w + 8.0, 22.0));
520:             grad_fill(&p, rr, 7.0, self.th.panel_top, self.th.panel_bottom);
521:             p.rect_stroke(rr.expand(1.0), cr(8.0), egui::Stroke::new(2.0, alpha(self.th.accent, 0.7)), egui::StrokeKind::Outside);
522:             let mut text = self.rename.as_ref().map(|r| r.text.clone()).unwrap_or_default();
523:             let first = self.rename.as_ref().is_some_and(|r| r.first);
524:             let id = Id::unique(("rename", &e.loc));
525:             let out = ui.put(rr.shrink2(vec2(4.0, 0.0)), egui::TextEdit::singleline(&mut text).id(id).frame(egui::Frame::NONE).font(font).text_color(self.th.ink1).vertical_align(egui::Align::Center).margin(egui::Margin::ZERO));
526:             if first {
527:                 out.request_focus();
528:                 if let Some(mut st) = egui::TextEdit::load_state(ui.ctx(), id) {
529:                     let stem = text.rfind('.').filter(|i| *i > 0 && !e.is_dir).map(|i| text[..i].chars().count()).unwrap_or(text.chars().count());
530:                     st.cursor.set_char_range(Some(egui::text::CCursorRange::two(egui::text::CCursor::new(0), egui::text::CCursor::new(stem))));
531:                     st.store(ui.ctx(), id);
532:                 }
533:                 if let Some(r) = self.rename.as_mut() {
534:                     r.first = false;
535:                 }
536:             }
537:             let enter = ui.input(|i| i.key_pressed(egui::Key::Enter));
538:             let esc = ui.input(|i| i.key_pressed(egui::Key::Escape));
539:             if let Some(r) = self.rename.as_mut() {
540:                 r.text = text.clone();
541:             }
542:             if enter || esc || (out.lost_focus() && !first) {
543:                 let loc = e.loc.clone();
544:                 self.rename = None;
545:                 if !esc {
546:                     match self.be.rename(&loc, &text) {
547:                         Ok(n) => {
548:                             self.select_after_list = vec![n];
549:                             self.load();
550:                         }
551:                         Err(m) => self.toast(m, false),
552:                     }
553:                 }
554:             }
555:             return max_w;
556:         }
557:         let display = if !self.st().show_extensions && !e.is_dir && !e.ext.is_empty() { e.name.trim_end_matches(&format!(".{}", e.ext)).to_string() } else { e.name.clone() };
558:         let t = self.fit(&p, &display, &font, max_w);
559:         let r = p.text(pos, Align2::LEFT_CENTER, t, font, col);
560:         r.width()
561:     }
