563:     fn tag_dots(&self, p: &Painter, e: &Entry, x: f32, cy: f32, max_x: f32) {
564:         let mut x = x;
565:         for col in self.tag_colors(&e.loc) {
566:             if x + 8.0 > max_x {
567:                 break;
568:             }
569:             let c0 = pos2(x + 4.0, cy);
570:             shadow(p, Rect::from_center_size(c0, vec2(6.0, 6.0)), 3.0, 1.0, 3.0, 0.0, alpha(col, 0.5));
571:             grad_fill(p, Rect::from_center_size(c0, vec2(7.0, 7.0)), 3.5, mix(col, Color32::WHITE, 0.3), col);
572:             x += 11.0;
573:         }
574:     }
