584:     /// The round tick that appears on hover (always, in selection mode). Returns true when it was clicked.
585:     fn tick_badge(&self, ui: &Ui, center: Pos2, id: impl std::hash::Hash + std::fmt::Debug, checked: bool, size: f32) -> bool {
586:         let p = ui.painter();
587:         let th = &self.th;
588:         let hit = Rect::from_center_size(center, vec2(size + 6.0, size + 6.0));
589:         let r = self.hit(ui, hit, id, Sense::click());
590:         let g = Rect::from_center_size(center, vec2(size, size));
591:         let pop = spring_to(ui.ctx(), ("tick", center.x as i32, center.y as i32, checked), if checked { 1.0 } else { 0.0 }, 260.0, 16.0);
592:         if checked || pop > 0.02 {
593:             let gs = Rect::from_center_size(center, vec2(size, size) * (0.86 + 0.18 * pop.clamp(0.0, 1.3)));
594:             let (c0, c1) = th.accent_grad();
595:             shadow(p, gs, size / 2.0, 2.0, 6.0, -1.0, alpha(th.accent, 0.5));
596:             grad_fill(p, gs, size / 2.0, c0, c1);
597:             rim(p, gs, size / 2.0, 1.0, Color32::from_white_alpha(150), true, size * 0.6);
598:             self.ico(p, "check-circle", Ic::Filled, center, size * 0.98, th.on_accent());
599:         } else {
600:             shadow(p, g, size / 2.0, 1.0, 3.0, 0.0, alpha(th.shadow, 0.25));
601:             grad_fill(p, g, size / 2.0, alpha(Color32::WHITE, if r.hovered() { 0.98 } else { 0.86 }), alpha(Color32::WHITE, if r.hovered() { 0.80 } else { 0.55 }));
602:             rim(p, g, size / 2.0, 1.0, Color32::WHITE, true, size * 0.6);
603:             p.circle_stroke(center, size / 2.0 - 1.0, egui::Stroke::new(1.2, alpha(th.ink3, if r.hovered() { 0.9 } else { 0.5 })));
604:         }
605:         r.clicked()
606:     }
