619:     fn folder_card(&mut self, ui: &mut Ui, i: usize, r: Rect) {
620:         let e = self.items[i].clone();
621:         let th = self.th.clone();
622:         let resp = self.item_interaction(ui, i, r, &e);
623:         let p = ui.painter().clone();
624:         let dragging = self.drag.is_some();
625:         let dropping = dragging && ui.rect_contains_pointer(r) && self.drag.as_ref().is_some_and(|d| !d.items.contains(&e.loc));
626:         let hov = resp.hovered();
627:         let a = self.anim(ui, ("fc", &e.loc), hov);
628:         let r = r.translate(vec2(0.0, -2.0 * a));
629:         let selected = self.sel.contains(&e.loc);
630:         let checked = selected && self.select_mode;
631:         DROP_TARGETS.with(|v| v.borrow_mut().push((DropTarget::Folder(e.loc.clone()), r)));
632:         elevate(&p, &th, r, 16.0, if a > 0.01 || dropping { 3 } else { 2 });
633:         grad_fill(&p, r, 16.0, mix(th.card_top, th.card_hover_top, a), th.card_bottom);
634:         rim(&p, r, 16.0, 1.3, th.rim, true, 36.0);
635:         rim(&p, r, 16.0, 1.0, th.rim_under, false, 6.0);
636:         if checked || dropping {
637:             grad_fill(&p, r, 16.0, th.accent_tint, th.accent_tint2);
638:             self.selection_ring(&p, r, 16.0);
639:         } else if selected {
640:             self.focus_ring(&p, r, 16.0);
641:         }
642:         let tile = Rect::from_min_size(r.min + vec2(12.0, 12.0), vec2(46.0, 46.0));
643:         grad_fill(&p, tile, 13.0, mix(th.accent_tint, Color32::WHITE, if th.dark { 0.0 } else { 0.55 }), alpha(th.accent, if th.dark { 0.20 } else { 0.16 }));
644:         rim(&p, tile, 13.0, 1.0, alpha(Color32::WHITE, if th.dark { 0.14 } else { 0.9 }), true, 18.0);
645:         self.ico(&p, if dropping { "folder-open" } else { "folder" }, Ic::Filled, tile.center(), 24.0, th.accent);
646:         let tx = tile.right() + 12.0;
647:         let max_w = r.right() - tx - 30.0;
648:         self.name_or_rename(ui, &e, pos2(tx, r.top() + 27.0), max_w, f_semi(T_BODY), th.ink1);
649:         let meta = match self.summaries.get(&e.loc) {
650:             Some((n, b)) => format!("{} item{} \u{b7} {}", n, if *n == 1 { "" } else { "s" }, format_size(*b)),
651:             None => "\u{2014}".into(),
652:         };
653:         p.text(pos2(tx, r.top() + 45.0), Align2::LEFT_CENTER, self.fit(&p, if dropping { "Drop to move here" } else { &meta }, &f_medium(T_META), max_w), f_medium(T_META), if dropping { th.accent_ink } else { th.ink3 });
654:         let n = self.tag_colors(&e.loc).len();
655:         self.tag_dots(&p, &e, r.right() - 14.0 - 11.0 * n as f32 + 3.0, r.center().y, r.right());
656:         if a > 0.05 || checked || self.select_mode {
657:             if self.tick_badge(ui, r.left_top() + vec2(12.0, 12.0), ("fchk", &e.loc), checked, 20.0) {
658:                 self.toggle_tick(&e.loc);
659:             }
660:         }
661:     }
662: 
663:     fn file_card(&mut self, ui: &mut Ui, i: usize, r: Rect, mh: f32) {
664:         let e = self.items[i].clone();
665:         let th = self.th.clone();
666:         self.request_thumb_for(&e);
667:         let resp = self.item_interaction(ui, i, r, &e);
668:         let p = ui.painter().clone();
669:         let hov = resp.hovered();
670:         let a = self.anim(ui, ("fl", &e.loc), hov);
671:         let lift = -2.0 * a;
672:         let media = Rect::from_min_size(r.min + vec2(0.0, lift), vec2(r.width(), mh));
673:         let selected = self.sel.contains(&e.loc);
674:         let checked = selected && self.select_mode;
675:         elevate(&p, &th, media, 14.0, if a > 0.01 { 3 } else { 2 });
676:         if let Some(t) = self.thumbs.get(&e.loc) {
677:             let sz = t.tex.size_vec2();
678:             textured_rrect(&p, media, 14.0, t.tex.id(), cover_uv(sz.x, sz.y, media), Color32::WHITE);
679:         } else {
680:             let kc = kind_color(e.kind, &th);
681:             grad_fill(&p, media, 14.0, mix(th.card_top, kc, if th.dark { 0.22 } else { 0.10 }), mix(th.card_bottom, kc, if th.dark { 0.12 } else { 0.18 }));
682:             let c = media.center();
683:             let tile = Rect::from_center_size(c, vec2(64.0, 64.0));
684:             grad_fill(&p, tile, 20.0, alpha(kc, 0.20), alpha(kc, 0.10));
685:             self.ico(&p, e.kind.icon(), Ic::Duo, c, 32.0, kc);
686:             if !e.ext.is_empty() {
687:                 p.text(pos2(c.x, media.bottom() - 18.0), Align2::CENTER_CENTER, e.ext.to_uppercase(), f_bold(10.5), alpha(kc, 0.9));
688:             }
689:         }
690:         rim(&p, media, 14.0, 1.2, alpha(Color32::WHITE, if th.dark { 0.14 } else { 0.55 }), true, 24.0);
691:         if checked {
692:             grad_fill(&p, media, 14.0, alpha(th.accent, 0.10), alpha(th.accent, 0.04));
693:             self.selection_ring(&p, media, 14.0);
694:         } else if selected {
695:             self.focus_ring(&p, media, 14.0);
696:         }
697:         if e.kind == Kind::Audio {
698:             let playing = self.audio_loc.as_ref() == Some(&e.loc) && self.be.audio.is_playing();
699:             if hov || playing {
700:                 let b = Rect::from_center_size(media.center(), vec2(44.0, 44.0));
701:                 let br = self.hit(ui, b, ("play", &e.loc), Sense::click());
702:                 raised_accent(&p, &th, b, 22.0, br.hovered(), br.is_pointer_button_down_on());
703:                 self.ico(&p, if playing { "pause" } else { "play" }, Ic::Filled, b.center() + vec2(if playing { 0.0 } else { 1.0 }, 0.0), 18.0, th.on_accent());
704:                 if br.clicked() {
705:                     self.acts.push(Act::TogglePlayPause(e.loc.clone()));
706:                 }
707:             }
708:         }
709:         if a > 0.05 || checked || self.select_mode {
710:             if self.tick_badge(ui, media.left_top() + vec2(19.0, 19.0), ("chk", &e.loc), checked, 22.0) {
711:                 self.toggle_tick(&e.loc);
712:             }
713:             if a > 0.05 {
714:                 let q = Rect::from_center_size(media.right_top() + vec2(-23.0, 23.0), vec2(30.0, 30.0));
715:                 let qr = self.hit(ui, q, ("qa", &e.loc), Sense::click());
716:                 raised(&p, &th, q, 15.0, qr.hovered(), qr.is_pointer_button_down_on());
717:                 self.ico(&p, "menu-dots", Ic::Duo, q.center(), 15.0, th.ink2);
718:                 if qr.clicked() {
719:                     self.sel.clear();
720:                     self.sel.insert(e.loc.clone());
721:                     self.menu = Some(Menu { kind: MenuKind::Item, pos: pos2(q.right(), q.bottom() + 6.0), target: Some(e.loc.clone()), device: None, sub: None, age: 0.0 });
722:                 }
723:                 if e.kind.previewable() && e.kind != Kind::Audio {
724:                     let q2 = Rect::from_center_size(media.right_top() + vec2(-59.0, 23.0), vec2(30.0, 30.0));
725:                     let qr2 = self.hit(ui, q2, ("qe", &e.loc), Sense::click());
726:                     raised(&p, &th, q2, 15.0, qr2.hovered(), qr2.is_pointer_button_down_on());
727:                     self.ico(&p, "eye", Ic::Duo, q2.center(), 15.0, th.ink3);
728:                     if qr2.clicked() {
729:                         self.acts.push(Act::Preview(e.loc.clone()));
730:                     }
731:                 }
732:             }
733:         }
