195:     fn native_resize_grips(&mut self, ctx: &egui::Context) {
196:         if IS_WEB {
197:             return;
198:         }
199:         use egui::viewport::ResizeDirection as D;
200:         let r = ctx.content_rect();
201:         let Some(p) = ctx.pointer_latest_pos() else { return };
202:         // Unified ResizeCursorOwner: 5px grips, but E/W edges are 2px so the
203:         // 14px scrollbar gutter at the right edge never fights the resize.
204:         let m = 5.0;
205:         let in_scrollbar_gutter = r.right() - p.x < 14.0 && p.x < r.right();
206:         if in_scrollbar_gutter && r.right() - p.x >= 2.0 {
207:             return; // pointer is over the scrollbar track — let it scroll
208:         }
209:         let (l, rr, t, b) = (
210:             p.x - r.left() < 2.0,
211:             r.right() - p.x < 2.0,
212:             p.y - r.top() < m,
213:             r.bottom() - p.y < m,
214:         );
215:         let dir = match (l, rr, t, b) {
216:             (true, _, true, _) => Some(D::NorthWest),
217:             (_, true, true, _) => Some(D::NorthEast),
218:             (true, _, _, true) => Some(D::SouthWest),
219:             (_, true, _, true) => Some(D::SouthEast),
220:             (true, ..) => Some(D::West),
221:             (_, true, ..) => Some(D::East),
222:             (_, _, true, _) => Some(D::North),
223:             (_, _, _, true) => Some(D::South),
224:             _ => None,
225:         };
226:         if let Some(d) = dir {
227:             ctx.set_cursor_icon(match d {
228:                 D::North | D::South => egui::CursorIcon::ResizeVertical,
229:                 D::East | D::West => egui::CursorIcon::ResizeHorizontal,
230:                 D::NorthWest | D::SouthEast => egui::CursorIcon::ResizeNwSe,
231:                 _ => egui::CursorIcon::ResizeNeSw,
232:             });
233:             if ctx.input(|i| i.pointer.primary_pressed()) {
234:                 ctx.send_viewport_cmd(egui::ViewportCommand::BeginResize(d));
235:             }
236:         }
237:     }
