239:     fn handle_keys(&mut self, ctx: &egui::Context) {
240:         use egui::Key;
241:         // the focused suite app (Terminal / Photos) owns the keyboard
242:         if IS_WEB && self.focused_app() != crate::shell::AppId::Files {
243:             let (cmd, k, comma) = ctx.input(|i| (i.modifiers.command, i.key_pressed(Key::K), i.key_pressed(Key::Comma)));
244:             if cmd && k {
245:                 self.act(Act::Palette);
246:             } else if cmd && comma {
247:                 self.app_cmd("settings");
248:             }
249:             return;
250:         }
251:         let typing = ctx.egui_wants_keyboard_input();
252:         let (cmd, shift, alt) = ctx.input(|i| (i.modifiers.command, i.modifiers.shift, i.modifiers.alt));
253:         let pressed = |k: Key| ctx.input(|i| i.key_pressed(k));
254:         let events: Vec<egui::Event> = ctx.input(|i| i.events.clone());
255:         if cmd && pressed(Key::K) {
256:             self.act(Act::Palette);
257:             return;
258:         }
259:         if cmd && pressed(Key::T) && !typing {
260:             self.act(Act::NewTab(None));
261:             return;
262:         }
263:         if cmd && pressed(Key::W) && !typing && self.tabs.len() > 1 {
264:             self.act(Act::CloseTab(self.tab_i));
265:             return;
266:         }
267:         if cmd && pressed(Key::Comma) {
268:             self.act(Act::Settings);
269:             return;
270:         }
271:         if pressed(Key::Escape) && self.search.sheet {
272:             self.act(Act::SearchSheet(false));
273:             return;
274:         }
275:         if pressed(Key::Escape) {
276:             if self.palette.open {
277:                 // palette handles its own Esc
278:             } else if self.menu.is_some() {
279:                 self.menu = None;
280:             } else if !matches!(self.modal, Modal::None) {
281:                 if let Modal::Preview(_) = self.modal {
282:                     self.be.audio.stop();
283:                 }
284:                 self.act(Act::CloseModal);
285:             } else if self.rename.is_some() {
286:                 self.rename = None;
287:             } else if self.ai.open && !typing {
288:                 self.ai.open = false;
289:             } else if self.search_active() {
290:                 self.clear_search();
291:             } else if !typing {
292:                 self.sel.clear();
293:                 self.select_mode = false;
294:             }
295:             return;
296:         }
297:         if self.palette.open {
298:             return;
299:         }
300:         // preview navigation
301:         if let Modal::Preview(l) = self.modal.clone() {
302:             let list: Vec<Location> = self.items.iter().filter(|x| x.kind.previewable()).map(|x| x.loc.clone()).collect();
303:             if let Some(i) = list.iter().position(|x| *x == l) {
304:                 if pressed(Key::ArrowRight) && i + 1 < list.len() {
305:                     self.act(Act::Preview(list[i + 1].clone()));
306:                 }
307:                 if pressed(Key::ArrowLeft) && i > 0 {
308:                     self.act(Act::Preview(list[i - 1].clone()));
309:                 }
310:             }
311:             if pressed(Key::Space) && !typing {
312:                 self.be.audio.stop();
313:                 self.act(Act::CloseModal);
314:             }
315:             return;
316:         }
317:         if !matches!(self.modal, Modal::None) {
318:             return;
319:         }
320:         if alt && pressed(Key::ArrowLeft) {
321:             self.act(Act::Back);
322:         }
323:         if alt && pressed(Key::ArrowRight) {
324:             self.act(Act::Forward);
325:         }
326:         if cmd && pressed(Key::Backslash) {
327:             self.act(Act::ToggleSidebar);
328:         }
329:         if cmd && pressed(Key::F) {
330:             self.act(Act::FocusSearch);
331:         }
332:         if pressed(Key::F5) {
333:             self.act(Act::Refresh);
334:         }
335:         if typing {
336:             return;
337:         }
338:         for e in &events {
339:             match e {
340:                 egui::Event::Copy => self.act(Act::Copy),
341:                 egui::Event::Cut => self.act(Act::Cut),
342:                 egui::Event::Paste(_) => self.act(Act::Paste),
343:                 _ => {}
344:             }
345:         }
346:         if cmd && pressed(Key::A) {
347:             self.act(Act::SelectAll);
348:         }
349:         if cmd && pressed(Key::I) {
350:             self.act(Act::Info);
351:         }
352:         if cmd && pressed(Key::D) {
353:             self.act(Act::Duplicate);
354:         }
355:         if cmd && pressed(Key::H) {
356:             self.act(Act::ToggleHidden);
357:         }
358:         if cmd && shift && pressed(Key::N) {
359:             self.act(Act::NewFolder);
360:         }
361:         if pressed(Key::F2) {
362:             if let Some(e) = self.selected().first() {
363:                 self.act(Act::Rename(e.loc.clone()));
364:             }
365:         }
366:         if pressed(Key::Delete) || (cmd && pressed(Key::Backspace)) {
367:             self.act(if shift { Act::DeleteForever } else { Act::Trash });
368:         }
369:         if pressed(Key::Enter) {
370:             self.act(Act::OpenSel);
371:         }
372:         if pressed(Key::Space) {
373:             let s = self.selected();
374:             if s.len() == 1 && s[0].kind.previewable() {
375:                 self.act(Act::Preview(s[0].loc.clone()));
376:             } else if s.len() == 1 && s[0].kind == smart_core::Kind::Audio {
377:                 self.act(Act::TogglePlayPause(s[0].loc.clone()));
378:             }
379:         }
380:         if (pressed(Key::Backspace) && !cmd) || (alt && pressed(Key::ArrowUp)) {
381:             self.act(Act::Up);
382:         }
383:         // arrow navigation
384:         if !self.search_active() && !self.items.is_empty() {
385:             let grid = self.st().grid;
386:             let cols = if grid { self.cols as i32 } else { 1 };
387:             let mut d = 0i32;
388:             if pressed(Key::ArrowRight) && grid { d = 1 }
389:             if pressed(Key::ArrowLeft) && grid { d = -1 }
390:             if pressed(Key::ArrowDown) { d = cols }
391:             if pressed(Key::ArrowUp) { d = -cols }
392:             if !alt && d != 0 {
393:                 let n = self.items.len() as i32;
394:                 let cur = self.focus.map(|f| f as i32).unwrap_or(if d > 0 { -cols.min(1) } else { n });
395:                 let next = (cur + d).clamp(0, n - 1) as usize;
396:                 self.focus = Some(next);
397:                 let loc = self.items[next].loc.clone();
398:                 if shift {
399:                     let a = self.anchor.unwrap_or(next);
400:                     let (lo, hi) = (a.min(next), a.max(next));
401:                     self.sel = self.items[lo..=hi].iter().map(|e| e.loc.clone()).collect();
402:                 } else {
403:                     self.sel = [loc].into_iter().collect();
404:                     self.anchor = Some(next);
405:                 }
406:                 self.scroll_to = Some(next);
407:             }
408:         }
409:         // single-key shortcuts (match the status-bar hints) and type-to-search
410:         if !cmd && !alt {
411:             if pressed(Key::G) { return self.act(Act::SetGrid(true)); }
412:             if pressed(Key::L) { return self.act(Act::SetGrid(false)); }
413:             if pressed(Key::D) { return self.act(Act::ToggleTheme); }
414:             if pressed(Key::T) { return self.act(Act::Modal(Modal::Tokens)); }
415:             if pressed(Key::Questionmark) { return self.act(Act::Modal(Modal::Shortcuts)); }
416:             if pressed(Key::Slash) { return self.act(Act::FocusSearch); }
417:             if self.st().typeahead {
418:                 for e in &events {
419:                     if let egui::Event::Text(t) = e {
420:                         if t.chars().all(|c| !c.is_control()) && !t.trim().is_empty() && self.rename.is_none() {
421:                             // Accumulate while typing is continuous (≤0.9 s between keys)
422:                             // so multi-character type-ahead actually works.
423:                             if self.time - self.type_at < 0.9 && !self.search.query.is_empty() {
424:                                 self.search.query.push_str(t);
425:                             } else {
426:                                 self.search.query = t.clone();
427:                             }
428:                             self.type_at = self.time;
429:                             self.search.dirty_at = self.time;
430:                             self.search.focus_next = true;
431:                             self.run_search();
432:                             return;
433:                         }
434:                     }
435:                 }
436:             }
437:         }
438:     }
439: }
