452: fn deep_link(a: &mut SmartApp) {
453:     use crate::shell::AppId;
454:     let h = web_sys::window().and_then(|w| w.location().hash().ok()).unwrap_or_default();
455:     let h = h.trim_start_matches('#');
456:     let (name, arg) = h.split_once('=').unwrap_or((h, ""));
457:     match name {
458:         "terminal" => {
459:             a.open_app(AppId::Terminal);
460:             a.shell.term.command("new");
461:             for c in arg.split(';').filter(|c| !c.is_empty()) {
462:                 a.term_submit(0, c.replace("%20", " "));
463:             }
464:         }
465:         "photos" => a.open_app(AppId::Photos),
466:         "top" => {
467:             a.open_app(AppId::Terminal);
468:             a.shell.term.command("new");
469:             a.term_submit(0, "top".into());
470:         }
471:         "palette" => {
472:             match arg {
473:                 "photos" => a.open_app(AppId::Photos),
474:                 "terminal" => a.open_app(AppId::Terminal),
475:                 _ => {}
476:             }
477:             a.act(Act::Palette);
478:         }
479:         "settings" => {
480:             let app = if arg == "terminal" { AppId::Terminal } else { AppId::Photos };
481:             a.open_app(app);
482:             a.shell.settings = Some((app, 0));
483:         }
484:         "photomenu" => {
485:             a.open_app(AppId::Photos);
