182:     /// Collapsed (icon-only) or expanded control, measured from the label.
183:     pub fn adaptive_button(&self, ui: &Ui, right: f32, cy: f32, icon: &'static str, label: &str, id: &str, kind: Btn, expanded: bool) -> (Response, f32) {
184:         let w = if expanded { self.tw(ui.painter(), label, &f_semi(T_BODY)) + 54.0 } else { 34.0 };
185:         let r = Rect::from_min_size(pos2(right - w, cy - 17.0), vec2(w, 34.0));
186:         let resp = if expanded {
187:             self.label_button(ui, r, Some(icon), label, id, kind)
188:         } else {
189:             let resp = self.icon_button(ui, r, icon, id, kind, true);
190:             resp
191:         };
192:         (resp, r.left() - 8.0)
193:     }
