439:         // one shared, draggable scroller (same component as every other app sidebar)
440:         let content_h = SB_H.with(|c| c.get());
441:         let off = self.vscroll(ui, nav, "files-side", content_h);
442:         self.sidebar_scroll = off;
443:         let pp = p.with_clip_rect(nav.intersect(ui.clip_rect()));
444:         let saved_clip = ui.clip_rect();
