450:     fn tree_children(&mut self, loc: &Location, now: f64) -> Vec<Location> {
451:         if let Some((t, v)) = self.tree_cache.get(loc) {
452:             if now - *t < 3.0 {
453:                 return v.clone();
454:             }
455:         }
456:         let v = self
457:             .be
458:             .registry
459:             .get(&loc.fs)
460:             .and_then(|fs| fs.list(&loc.path).ok())
461:             .map(|l| {
462:                 let mut d: Vec<Entry> = l.into_iter().filter(|e| e.is_dir && !e.hidden).collect();
463:                 d.sort_by(|a, b| natural_cmp(&a.name, &b.name));
464:                 d.into_iter().map(|e| e.loc).collect::<Vec<_>>()
465:             })
466:             .unwrap_or_default();
467:         self.tree_cache.insert(loc.clone(), (now, v.clone()));
468:         v
469:     }
