471:     /// Flattened, depth-first view of the expanded folder tree rooted at Home.
472:     fn tree_flat(&mut self, now: f64) -> Vec<(Location, usize, String, bool, bool)> {
473:         let root = self.be.home();
474:         if !self.tree_init {
475:             self.tree_init = true;
476:             self.tree_open.insert(root.clone());
477:         }
478:         let mut out = vec![];
479:         let mut stack = vec![(root, 0usize)];
480:         while let Some((loc, depth)) = stack.pop() {
481:             let kids = self.tree_children(&loc, now);
482:             let open = self.tree_open.contains(&loc);
483:             let name = if depth == 0 { "Home".to_string() } else { loc.name() };
484:             out.push((loc.clone(), depth, name, !kids.is_empty(), open));
485:             if open && depth < 6 && out.len() < 300 {
486:                 for k in kids.iter().rev() {
487:                     stack.push((k.clone(), depth + 1));
488:                 }
489:             }
490:         }
491:         out
492:     }
