494:     fn sidebar_rows(&mut self, ui: &Ui, p: &Painter, nav: Rect, dy: f32) {
495:         let th = self.th.clone();
496:         let x0 = nav.left() + 12.0;
497:         let w = SIDEBAR_W - 24.0;
498:         let cur = self.route.clone();
499:         let mut y = nav.top() + dy + 12.0;
500:         let label = |y: f32, s: &str, n: Option<usize>| {
501:             p.text(pos2(nav.left() + 20.0, y + 7.0), Align2::LEFT_CENTER, s.to_uppercase(), f_semi(T_LABEL), th.ink4);
502:             if let Some(n) = n {
503:                 p.text(pos2(nav.left() + 20.0 + 64.0, y + 7.0), Align2::LEFT_CENTER, n.to_string(), f_medium(10.0), alpha(th.ink4, 0.8));
504:             }
505:         };
506:         let base = nav.top() + dy;
507:         // ── Favorites
508:         label(y, "Favorites", None);
509:         y += 22.0;
510:         let mut rows: Vec<(String, &'static str, Route, Option<usize>, Option<Location>)> = vec![];
511:         let places = self.places.clone();
512:         for pl in &places {
513:             rows.push((pl.title.clone(), pl.icon, Route::Loc(pl.loc.clone()), self.place_counts.get(&pl.loc).copied(), Some(pl.loc.clone())));
514:             if pl.id == "home" {
515:                 rows.push(("Recents".into(), "clock-circle", Route::Recents, None, None));
516:                 rows.push(("Storage".into(), "ssd-square", Route::Storage, None, None));
517:                 rows.push(("Trash".into(), "trash-bin-minimalistic", Route::Trash, None, None));
518:             }
519:         }
520:         for pin in self.lib(|l| l.pins.clone()) {
521:             rows.insert(1, (pin.name(), "folder", Route::Loc(pin.clone()), None, Some(pin)));
522:         }
523:         for (name, icon, route, count, loc) in rows {
524:             // Un-pin pop: the row shrinks away over 0.22 s before being removed.
525:             let k = loc.as_ref().and_then(|l| self.pin_anim.get(&l.path)).map(|s| ((self.time - *s) / 0.22).clamp(0.0, 1.0) as f32).unwrap_or(0.0);
526:             if k >= 0.99 {
527:                 continue;
528:             }
529:             if k > 0.0 {
530:                 ui.ctx().request_repaint();
531:             }
532:             let hh = 32.0 * (1.0 - k);
533:             let rect = Rect::from_min_size(pos2(x0, y), vec2(w, hh));
534:             let active = cur == route;
535:             let visible = rect.bottom() > nav.top() - 4.0 && rect.top() < nav.bottom() + 4.0;
536:             let dropping = self.drag.is_some() && visible && ui.rect_contains_pointer(rect);
537:             if visible {
538:                 if let Some(l) = &loc {
539:                     DROP_TARGETS.with(|v| v.borrow_mut().push((DropTarget::Place(l.clone()), rect)));
540:                 }
541:                 self.sb_row(ui, rect, icon, &name, active, count.map(|c| c.to_string()), dropping, &format!("place-{}", name));
542:             }
543:             if visible {
544:                 let r = self.hit(ui, rect, ("sbrow", format!("place-{}", name)), Sense::click());
545:                 if r.clicked() {
546:                     self.push_act(Act::Nav(route.clone()));
547:                 }
548:                 if r.secondary_clicked() {
549:                     if let Some(l) = loc.clone() {
550:                         self.menu = Some(Menu { kind: MenuKind::Place, pos: ui.ctx().pointer_latest_pos().unwrap_or(rect.center()), target: Some(l), device: None, sub: None, age: 0.0 });
551:                     }
552:                 }
553:             }
554:             y += 33.0 * (1.0 - k);
555:         }
556:         // While dragging, the Favorites block becomes a "pin here" drop zone.
557:         if let Some(drag) = self.drag.as_ref() {
558:             if let Some(src) = drag.items.first().cloned() {
559:                 let already = self.lib(|l| l.pins.contains(&src));
560:                 if !already {
561:                     let fav_top = nav.top() + 34.0;
562:                     let zone = Rect::from_min_max(pos2(x0 - 2.0, fav_top), pos2(x0 + w + 2.0, y.max(fav_top + 40.0).min(nav.bottom())));
563:                     let over = ui.rect_contains_pointer(zone);
564:                     if over {
565:                         p.rect_stroke(zone.shrink(1.0), cr(12.0), egui::Stroke::new(1.6, th.accent), egui::StrokeKind::Inside);
566:                         grad_fill(&p, zone, 12.0, alpha(th.accent, 0.12), alpha(th.accent, 0.05));
567:                         p.text(pos2(zone.center().x, zone.center().y), Align2::CENTER_CENTER, "Pin to Favorites", f_semi(T_META), th.accent_ink);
568:                         ui.ctx().request_repaint();
569:                     }
570:                     DROP_TARGETS.with(|v| v.borrow_mut().push((DropTarget::Pin(src), zone)));
571:                 }
572:             }
573:         }
574:         // ── Locations
575:         y += 14.0;
576:         label(y, "Locations", None);
577:         y += 23.0;
578:         for d in self.devices.clone() {
579:             let rect = Rect::from_min_size(pos2(x0, y), vec2(w, 32.0));
580:             let active = matches!(&cur, Route::Loc(l) if d.loc.as_ref().is_some_and(|dl| l == dl || (d.kind != DeviceKind::Internal && l.fs == dl.fs && l.starts_with(dl))));
581:             let visible = rect.bottom() > nav.top() - 4.0 && rect.top() < nav.bottom() + 4.0;
582:             let dropping = self.drag.is_some() && visible && d.mounted && ui.rect_contains_pointer(rect);
583:             if visible {
584:                 if let (Some(l), true) = (&d.loc, d.mounted) {
585:                     DROP_TARGETS.with(|v| v.borrow_mut().push((DropTarget::Place(l.clone()), rect)));
586:                 }
587:                 self.sb_row_device(ui, rect, &d, active, dropping);
588:                 let r = self.hit(ui, rect, ("dev", &d.id), Sense::click());
589:                 if r.clicked() {
590:                     match (&d.loc, d.mounted, d.kind) {
591:                         (_, _, DeviceKind::Phone) => self.push_act(Act::Modal(Modal::Phone)),
592:                         (Some(l), true, _) => self.push_act(Act::Nav(Route::Loc(l.clone()))),
593:                         _ => self.push_act(Act::Mount(d.id.clone())),
594:                     }
595:                 }
596:                 if r.secondary_clicked() {
597:                     self.menu = Some(Menu { kind: MenuKind::Device, pos: ui.ctx().pointer_latest_pos().unwrap_or(rect.center()), target: d.loc.clone(), device: Some(d.id.clone()), sub: None, age: 0.0 });
598:                 }
599:             }
600:             y += 33.0;
601:         }
602:         {
603:             let rect = Rect::from_min_size(pos2(x0, y), vec2(w, 32.0));
604:             let visible = rect.bottom() > nav.top() - 4.0 && rect.top() < nav.bottom() + 4.0;
605:             if visible {
606:                 if self.sb_row(ui, rect, "add", "Mount a device\u{2026}", false, None, false, "mount-dev").clicked() {
607:                     self.push_act(Act::Modal(Modal::Devices));
608:                 }
609:             }
610:             y += 33.0;
611:         }
612:         // ── Folder tree
613:         y += 14.0;
614:         label(y, "Folders", None);
615:         y += 23.0;
616:         let now = self.time;
617:         let flat = self.tree_flat(now);
618:         for (loc, depth, name, has_kids, open) in flat {
619:             let rect = Rect::from_min_size(pos2(x0, y), vec2(w, 28.0));
620:             let visible = rect.bottom() > nav.top() - 4.0 && rect.top() < nav.bottom() + 4.0;
621:             if visible {
622:                 let active = cur == Route::Loc(loc.clone());
623:                 let dropping = self.drag.is_some() && ui.rect_contains_pointer(rect);
624:                 DROP_TARGETS.with(|v| v.borrow_mut().push((DropTarget::Place(loc.clone()), rect)));
625:                 let r = self.hit(ui, rect, ("tree", &loc), Sense::click());
626:                 if active || dropping {
627:                     p.rect_filled(rect, cr(10.0), th.accent_tint);
628:                 } else if r.is_pointer_button_down_on() {
629:                     p.rect_filled(rect, cr(10.0), th.row_press);
630:                 } else if r.hovered() {
631:                     p.rect_filled(rect, cr(10.0), th.row_hover);
632:                 }
633:                 let ind = 6.0 + depth as f32 * 14.0;
634:                 if has_kids {
635:                     let cb = Rect::from_center_size(pos2(rect.left() + ind + 9.0, rect.center().y), vec2(20.0, 20.0));
636:                     let cresp = self.hit(ui, cb, ("treechev", &loc), Sense::click());
637:                     let t = spring_to(ui.ctx(), ("tree-rot", &loc), if open { 1.0 } else { 0.0 }, 320.0, 24.0);
638:                     if cresp.hovered() {
639:                         p.circle_filled(cb.center(), 9.0, th.row_press);
640:                     }
641:                     let ang = t * std::f32::consts::FRAC_PI_2;
642:                     let rot = |v: egui::Vec2| vec2(v.x * ang.cos() - v.y * ang.sin(), v.x * ang.sin() + v.y * ang.cos());
643:                     let s = egui::Stroke::new(1.6, if cresp.hovered() { th.ink2 } else { th.ink4 });
644:                     let (a0, a1, a2) = (rot(vec2(-1.5, -3.5)), rot(vec2(2.0, 0.0)), rot(vec2(-1.5, 3.5)));
645:                     p.line_segment([cb.center() + a0, cb.center() + a1], s);
646:                     p.line_segment([cb.center() + a1, cb.center() + a2], s);
647:                     if cresp.clicked() {
648:                         if !self.tree_open.remove(&loc) {
649:                             self.tree_open.insert(loc.clone());
650:                         }
651:                     }
652:                 }
653:                 let ix = rect.left() + ind + 30.0;
654:                 self.ico(p, if open || active { "folder-open" } else { "folder" }, if active { Ic::Filled } else { Ic::Duo }, pos2(ix, rect.center().y), 15.0, if active { th.accent_ink } else { th.ink3 });
655:                 let f = if active { f_semi(T_BODY) } else { f_medium(T_BODY) };
656:                 p.text(pos2(ix + 15.0, rect.center().y), Align2::LEFT_CENTER, self.fit(p, &name, &f, (rect.right() - ix - 22.0).max(20.0)), f, if active { th.accent_ink } else { th.ink2 });
657:                 if r.clicked() {
658:                     self.push_act(Act::Nav(Route::Loc(loc.clone())));
659:                     if has_kids && !open {
660:                         self.tree_open.insert(loc.clone());
661:                     }
662:                 }
663:                 if r.secondary_clicked() {
664:                     self.menu = Some(Menu { kind: MenuKind::Place, pos: ui.ctx().pointer_latest_pos().unwrap_or(rect.center()), target: Some(loc.clone()), device: None, sub: None, age: 0.0 });
665:                 }
666:             }
667:             y += 29.0;
668:         }
669:         // ── Tags
670:         y += 14.0;
671:         let tags = self.lib(|l| l.tags.clone());
672:         label(y, "Tags", None);
673:         y += 23.0;
674:         for t in tags {
675:             let rect = Rect::from_min_size(pos2(x0, y), vec2(w, 32.0));
676:             let active = cur == Route::Tag(t.id.clone());
677:             let n = self.lib(|l| l.tag_count(&t.id));
678:             let visible = rect.bottom() > nav.top() - 4.0 && rect.top() < nav.bottom() + 4.0;
679:             let dropping = self.drag.is_some() && visible && ui.rect_contains_pointer(rect);
680:             if visible {
681:                 DROP_TARGETS.with(|v| v.borrow_mut().push((DropTarget::Tag(t.id.clone()), rect)));
682:                 let r = self.sb_row_tag(ui, rect, &t.name, hex(&t.color), active, n, dropping);
683:                 if r.clicked() {
684:                     self.push_act(Act::Nav(Route::Tag(t.id.clone())));
685:                 }
686:             }
687:             y += 33.0;
688:         }
689:         {
690:             let rect = Rect::from_min_size(pos2(x0, y), vec2(w, 32.0));
691:             let visible = rect.bottom() > nav.top() - 4.0 && rect.top() < nav.bottom() + 4.0;
692:             if visible && self.sb_row(ui, rect, "add", "New tag\u{2026}", false, None, false, "new-tag").clicked() {
693:                 self.push_act(Act::Modal(Modal::NewTag));
694:             }
695:             y += 33.0;
696:         }
697:         y += 12.0;
698:         // store content height for the scroll clamp
699:         let content = (y - base + 6.0).max(1.0);
700:         SB_H.with(|c| c.set(content));
701:     }
