41: impl Scan {
42:     pub fn new(reg: Arc<Registry>, root: &Location) -> Self {
43:         Self {
44:             root: root.clone(),
45:             reg,
46:             stack: vec![root.clone()],
47:             stats: ScanStats::default(),
48:             cap: 6,
49:             top: Vec::new(),
50:             largest: Vec::new(),
51:         }
52:     }
53: 
54:     pub fn with_registry(reg: Arc<Registry>, root: &Location) -> Self {
55:         Self::new(reg, root)
56:     }
