160:     pub fn nodes(&self) -> Vec<ScanNode> {
161:         let mut v = self.top.clone();
162:         v.sort_by(|a, b| b.bytes.cmp(&a.bytes).then_with(|| a.name.cmp(&b.name)));
163:         v
164:     }
