412:     fn preview_audio(&mut self, ui: &mut Ui, media: Rect, e: &Entry) {
413:         let p = ui.painter().clone();
414:         let th = self.th.clone();
415:         let kc = th.warn;
416:         let c = media.center();
417:         let art = Rect::from_center_size(c - vec2(0.0, 92.0), vec2(120.0, 120.0));
418:         elevate(&p, &th, art, 30.0, 3);
419:         grad_fill(&p, art, 30.0, mix(kc, Color32::WHITE, 0.2), mix(kc, Color32::BLACK, 0.2));
420:         rim(&p, art, 30.0, 1.4, Color32::from_white_alpha(120), true, 50.0);
421:         self.ico(&p, "music-notes", Ic::Filled, art.center(), 54.0, Color32::from_white_alpha(235));
422:         let wf: Vec<f32> = self.waveform.as_ref().filter(|(l, _)| *l == e.loc).map(|(_, w)| w.clone()).unwrap_or_default();
423:         let wr = Rect::from_center_size(c + vec2(0.0, 36.0), vec2((media.width() - 120.0).min(640.0), 80.0));
424:         let playing_this = self.audio_loc.as_ref() == Some(&e.loc);
425:         let pos = if playing_this { self.be.audio.position() } else { 0.0 };
426:         let dur = if playing_this { self.be.audio.duration() } else { None }.or_else(|| Some((e.size as f32 / 176_400.0).max(1.0)));
427:         let frac = dur.map(|d| (pos / d).clamp(0.0, 1.0)).unwrap_or(0.0);
428:         let n = wf.len().max(1);
429:         let bw = wr.width() / n as f32;
430:         for (i, v) in wf.iter().enumerate() {
431:             let h = (wr.height() * v).max(3.0);
432:             let r = Rect::from_center_size(pos2(wr.left() + bw * (i as f32 + 0.5), wr.center().y), vec2((bw - 2.0).max(1.5), h));
433:             let played = (i as f32 / n as f32) < frac;
434:             grad_fill(&p, r, 1.5, if played { th.accent } else { alpha(th.ink2, 0.35) }, if played { th.accent_press } else { alpha(th.ink2, 0.2) });
435:         }
436:         let seek = self.hit(ui, wr, "wf-seek", Sense::click());
437:         if seek.clicked() && playing_this {
438:             if let (Some(pp), Some(d)) = (seek.interact_pointer_pos(), dur) {
439:                 self.be.audio.seek(((pp.x - wr.left()) / wr.width()).clamp(0.0, 1.0) * d);
440:             }
441:         }
442:         let fmt = |s: f32| format!("{}:{:02}", (s as u32) / 60, (s as u32) % 60);
443:         p.text(pos2(wr.left(), wr.bottom() + 16.0), Align2::LEFT_CENTER, fmt(pos), f_semi(T_META), th.ink3);
444:         p.text(pos2(wr.right(), wr.bottom() + 16.0), Align2::RIGHT_CENTER, dur.map(fmt).unwrap_or_default(), f_semi(T_META), th.ink3);
445:         let btn = Rect::from_center_size(pos2(c.x, wr.bottom() + 58.0), vec2(56.0, 56.0));
446:         let playing = playing_this && self.be.audio.is_playing();
447:         let r = self.hit(ui, btn, "pv-play", Sense::click());
448:         raised_accent(&p, &th, btn, 28.0, r.hovered(), r.is_pointer_button_down_on());
449:         self.ico(&p, if playing { "pause" } else { "play" }, Ic::Filled, btn.center() + vec2(if playing { 0.0 } else { 1.5 }, 0.0), 24.0, th.on_accent());
450:         if r.clicked() {
451:             if playing {
452:                 self.be.audio.pause();
453:             } else if playing_this && self.be.audio.is_loaded() {
454:                 self.be.audio.resume();
455:             } else {
456:                 self.acts.push(Act::Play(e.loc.clone()));
457:             }
458:         }
459:         if playing {
460:             ui.ctx().request_repaint();
461:         }
462:     }
