465:     fn m_info(&mut self, ui: &mut Ui, card: Rect, ls: &[Location], close: &mut bool) {
466:         let p = ui.painter().clone();
467:         let th = self.th.clone();
468:         let ents: Vec<Entry> = ls.iter().filter_map(|l| self.be.stat(l).ok()).collect();
469:         let multi = ents.len() > 1;
470:         let title = if multi { format!("{} items", ents.len()) } else { ents.first().map(|e| e.name.clone()).unwrap_or_default() };
471:         let sub = if multi { "Multiple selection".to_string() } else { ents.first().map(|e| e.kind_label()).unwrap_or_default() };
472:         if self.modal_head(ui, card, "info-circle", &title, &sub, true) {
473:             *close = true;
474:         }
475:         let Some(first) = ents.first().cloned() else { return };
476:         // hero
477:         let hero = Rect::from_min_size(card.min + vec2(22.0, 76.0), vec2(card.width() - 44.0, 130.0));
478:         grad_fill(&p, hero, 16.0, alpha(kind_color(first.kind, &th), 0.14), alpha(kind_color(first.kind, &th), 0.06));
479:         if let (Some(t), false) = (self.thumbs.get(&first.loc), multi) {
480:             let sz = t.tex.size_vec2();
481:             let r = Rect::from_center_size(hero.center(), vec2(150.0, 100.0));
482:             elevate(&p, &th, r, 12.0, 2);
483:             textured_rrect(&p, r, 12.0, t.tex.id(), cover_uv(sz.x, sz.y, r), Color32::WHITE);
484:         } else {
485:             let kc = kind_color(first.kind, &th);
486:             let t = Rect::from_center_size(hero.center(), vec2(84.0, 84.0));
487:             grad_fill(&p, t, 26.0, alpha(kc, 0.26), alpha(kc, 0.12));
488:             rim(&p, t, 26.0, 1.2, Color32::from_white_alpha(if th.dark { 40 } else { 160 }), true, 30.0);
489:             self.ico(&p, if multi { "copy" } else { first.kind.icon() }, if first.is_dir { Ic::Filled } else { Ic::Duo }, t.center(), 40.0, kc);
490:         }
491:         let total: u64 = ents.iter().map(|e| e.size).sum();
492:         let mut rows: Vec<(&str, String)> = vec![];
493:         if multi {
494:             rows.push(("Total size", format_size(total)));
495:             rows.push(("Folders", ents.iter().filter(|e| e.is_dir).count().to_string()));
496:             rows.push(("Files", ents.iter().filter(|e| !e.is_dir).count().to_string()));
497:         } else {
498:             rows.push(("Kind", first.kind_label()));
499:             rows.push(("MIME", self.be.mime_of(&first.loc)));
500:             if first.is_dir {
501:                 let s = self.summaries.get(&first.loc).map(|(n, b)| format!("{} item{} \u{b7} {}", n, if *n == 1 { "" } else { "s" }, format_size(*b))).unwrap_or("Calculating\u{2026}".into());
502:                 rows.push(("Contains", s));
503:             } else {
504:                 rows.push(("Size", format!("{}  ({} bytes)", format_size(first.size), first.size)));
505:                 if let Some(t) = self.thumbs.get(&first.loc).and_then(|t| t.orig) {
506:                     rows.push(("Dimensions", format!("{} \u{d7} {} px", t.0, t.1)));
507:                 }
508:             }
509:             rows.push(("Where", self.pretty_path(&first.loc.parent().unwrap_or(first.loc.clone()))));
510:             if let Some(m) = first.modified {
511:                 rows.push(("Modified", format_full_date(m)));
512:             }
513:             rows.push(("Permissions", format!("{} · {}", if first.readonly { "Read only" } else { "Read & write" }, if first.executable { "Executable" } else { "Not executable" })));
514:             if let Some(real) = self.be.registry.get(&first.loc.fs).and_then(|v| v.real_path(&first.loc.path)) {
515:                 rows.push(("Path", real.to_string_lossy().to_string()));
516:             }
517:         }
518:         let mut y = hero.bottom() + 16.0;
519:         for (k, v) in rows {
520:             p.text(pos2(card.left() + 28.0, y + 10.0), Align2::LEFT_CENTER, k, f_medium(T_META), th.ink3);
521:             p.text(pos2(card.left() + 136.0, y + 10.0), Align2::LEFT_CENTER, self.fit(&p, &v, &f_semi(T_BODY), card.width() - 170.0), f_semi(T_BODY), th.ink1);
522:             y += 28.0;
523:         }
524:         // tags
525:         y += 8.0;
526:         p.text(pos2(card.left() + 28.0, y + 12.0), Align2::LEFT_CENTER, "Tags", f_medium(T_META), th.ink3);
527:         let mut x = card.left() + 136.0;
528:         for t in self.lib(|l| l.tags.clone()) {
529:             let on = ents.iter().all(|e| self.lib(|l| l.has_tag(&e.loc, &t.id)));
530:             let f = f_semi(11.5);
531:             let wd = self.tw(&p, &t.name, &f) + 38.0;
532:             let r = Rect::from_min_size(pos2(x, y), vec2(wd, 26.0));
533:             let resp = self.hit(ui, r, ("info-tag", &t.id), Sense::click());
534:             let col = hex(&t.color);
535:             if on {
536:                 grad_fill(&p, r, 13.0, alpha(col, 0.28), alpha(col, 0.16));
537:             } else {
538:                 raised(&p, &th, r, 13.0, resp.hovered(), false);
539:             }
540:             grad_fill(&p, Rect::from_center_size(pos2(r.left() + 14.0, r.center().y), vec2(8.0, 8.0)), 4.0, mix(col, Color32::WHITE, 0.3), col);
541:             p.text(pos2(r.left() + 26.0, r.center().y), Align2::LEFT_CENTER, &t.name, f, th.ink1);
542:             if resp.clicked() {
543:                 for e in &ents {
544:                     let has = self.lib(|l| l.has_tag(&e.loc, &t.id));
545:                     if has == on {
546:                         self.be.library.write().unwrap().toggle_tag(&e.loc, &t.id);
547:                     }
548:                 }
549:             }
