570:     fn m_openwith(&mut self, ui: &mut Ui, card: Rect, l: &Location, close: &mut bool) {
571:         let p = ui.painter().clone();
572:         let th = self.th.clone();
573:         if self.modal_head(ui, card, "share", "Open with\u{2026}", &l.name(), true) {
574:             *close = true;
575:         }
576:         let apps = self.be.apps_for(l);
577:         let mut y = card.top() + 84.0;
578:         let row = |app: &mut Self, ui: &mut Ui, y: f32, icon: &'static str, real: Option<String>, name: &str, sub: &str, id: String, is_default: bool| -> (bool, bool) {
579:             let r = Rect::from_min_size(pos2(card.left() + 16.0, y), vec2(card.width() - 32.0, 52.0));
580:             let resp = app.hit(ui, r, ("owrow", &id), Sense::click());
581:             let p = ui.painter();
582:             if resp.hovered() {
583:                 grad_fill(p, r, 14.0, app.th.row_press, app.th.row_hover);
584:             }
585:             let ic = Rect::from_min_size(r.min + vec2(10.0, 8.0), vec2(36.0, 36.0));
586:             let tex = real.as_deref().and_then(|pth| app.app_icon_tex(ui.ctx(), pth));
587:             if let Some(t) = tex {
588:                 // Real desktop icon, letterboxed inside the rounded tile.
589:                 well(p, &app.th, ic, 11.0);
590:                 let side = ic.width().min(ic.height()) - 8.0;
591:                 let inner = Rect::from_center_size(ic.center(), vec2(side, side));
592:                 textured_rrect(p, inner, 8.0, t.id(), Rect::from_min_max(pos2(0.0, 0.0), pos2(1.0, 1.0)), Color32::WHITE);
593:             } else {
594:                 grad_fill(p, ic, 11.0, alpha(app.th.accent, 0.16), alpha(app.th.accent, 0.08));
595:                 rim(p, ic, 11.0, 1.0, Color32::from_white_alpha(if app.th.dark { 30 } else { 150 }), true, 14.0);
596:                 app.ico(p, icon, Ic::Duo, ic.center(), 18.0, app.th.accent_ink);
597:             }
598:             p.text(pos2(ic.right() + 12.0, r.center().y - 8.0), Align2::LEFT_CENTER, name, f_semi(T_BODY), app.th.ink1);
599:             p.text(pos2(ic.right() + 12.0, r.center().y + 9.0), Align2::LEFT_CENTER, sub, f_medium(T_META), app.th.ink3);
600:             let mut always = false;
601:             if resp.hovered() && !id.starts_with("default") {
602:                 let b = Rect::from_center_size(pos2(r.right() - 56.0, r.center().y), vec2(92.0, 28.0));
603:                 always = app.label_button(ui, b, None, "Always", &format!("al-{}", id), Btn::Raised).clicked();
604:             }
605:             if is_default {
606:                 let b = Rect::from_center_size(pos2(r.right() - 36.0, r.center().y), vec2(56.0, 22.0));
607:                 grad_fill(ui.painter(), b, 11.0, alpha(app.th.good, 0.2), alpha(app.th.good, 0.12));
608:                 ui.painter().text(b.center(), Align2::CENTER_CENTER, "Default", f_semi(10.5), app.th.good);
609:             }
610:             (resp.clicked() && !always, always)
611:         };
612:         let _ = &p;
613:         let (clicked, _) = row(self, ui, y, "arrow-right-up", None, "System default", "Opens with whatever your system prefers", "default-sys".into(), false);
614:         if clicked {
615:             self.be.open(l);
616:             *close = true;
617:         }
618:         y += 56.0;
619:         if apps.is_empty() {
620:             p.text(pos2(card.center().x, y + 60.0), Align2::CENTER_CENTER, "No other applications are registered for this type", f_medium(T_BODY), th.ink3);
621:         }
622:         for a in apps.iter().take(6) {
623:             let (c, always) = row(self, ui, y, a.icon, a.icon_path.clone(), &a.name, if a.is_default { "Current default for this type" } else { "Application" }, a.id.clone(), a.is_default);
624:             if c {
625:                 self.be.open_with(l, a);
626:                 *close = true;
627:             }
628:             if always {
629:                 self.acts.push(Act::SetDefault(l.clone(), a.clone()));
630:                 self.be.open_with(l, a);
631:                 *close = true;
632:             }
633:             y += 56.0;
634:         }
635:         self.modal_foot_note(&p, card, "Nothing leaves this device until you send it.", 300.0);
636:         let mut cur = card.right() - 22.0;
637:         if self.foot_btn(ui, card, &mut cur, "Done", Btn::Raised, "ow-done") {
638:             *close = true;
639:         }
640:     }
