771:     fn m_confirm(&mut self, ui: &mut Ui, card: Rect, cf: &Confirm, close: &mut bool, acts: &mut Vec<Act>) {
772:         let p = ui.painter().clone();
773:         let th = self.th.clone();
774:         let orb = Rect::from_min_size(card.min + vec2(22.0, 22.0), vec2(40.0, 40.0));
775:         let col = if cf.danger { th.danger } else { th.accent };
776:         grad_fill(&p, orb, 20.0, alpha(col, 0.22), alpha(col, 0.12));
777:         rim(&p, orb, 20.0, 1.2, Color32::from_white_alpha(if th.dark { 40 } else { 160 }), true, 20.0);
778:         self.ico(&p, if cf.danger { "trash-bin-minimalistic" } else { "info-circle" }, Ic::Filled, orb.center(), 20.0, col);
779:         p.text(pos2(orb.right() + 14.0, orb.center().y - 9.0), Align2::LEFT_CENTER, self.fit(&p, &cf.title, &f_bold(T_TITLE), card.width() - 100.0), f_bold(T_TITLE), th.ink1);
780:         p.text(pos2(orb.right() + 14.0, orb.center().y + 11.0), Align2::LEFT_CENTER, self.fit(&p, &cf.body, &f_medium(T_META), card.width() - 100.0), f_medium(T_META), th.ink3);
781:         // Permanent deletes require typing the exact (case-sensitive) file name.
782:         let can_proceed = match &cf.expect {
783:             Some(want) => {
784:                 let fld = Rect::from_min_size(pos2(card.left() + 22.0, card.top() + 76.0), vec2(card.width() - 44.0, 36.0));
785:                 well(&p, &th, fld, 10.0);
786:                 p.text(pos2(fld.left() + 12.0, fld.top() - 10.0), Align2::LEFT_CENTER, format!("Type “{}” exactly to confirm", want), f_medium(T_META), th.ink3);
787:                 let mut t = std::mem::take(&mut self.confirm_input);
788:                 let out = ui.put(fld.shrink2(vec2(12.0, 4.0)), egui::TextEdit::singleline(&mut t).id(egui::Id::new("cf-expect")).frame(egui::Frame::NONE).font(f_medium(T_BODY)).text_color(th.ink1).vertical_align(egui::Align::Center).margin(egui::Margin::ZERO));
789:                 let ok = t == *want;
790:                 self.confirm_input = t;
791:                 if !out.has_focus() && (self.confirm_input != *want) {
792:                     out.request_focus();
793:                 }
794:                 ok
795:             }
796:             None => true,
797:         };
798:         let mut cur = card.right() - 22.0;
799:         let w = self.tw(&p, &cf.ok, &f_semi(T_BODY)) + 34.0;
800:         let r = Rect::from_min_size(pos2(cur - w, card.bottom() - 54.0), vec2(w, 36.0));
801:         cur -= w + 8.0;
802:         let resp = self.hit(ui, r, "cf-ok", Sense::click());
803:         if cf.danger {
804:             let (a, b) = if th.dark { (hex("#ff8a93"), hex("#e5525e")) } else { (hex("#dc5560"), hex("#bd3441")) };
805:             let ghost = !can_proceed;
806:             shadow(&p, r, 18.0, 5.0, 14.0, -4.0, alpha(th.danger, if ghost { 0.1 } else { 0.4 }));
807:             grad_fill(&p, r, 18.0, if ghost { mix(th.well, th.ink4, 0.3) } else if resp.hovered() { mix(a, Color32::WHITE, 0.1) } else { a }, if ghost { th.well } else { b });
808:             rim(&p, r, 18.0, 1.3, Color32::from_white_alpha(140), true, 20.0);
809:             p.text(r.center(), Align2::CENTER_CENTER, &cf.ok, f_semi(T_BODY), if ghost { th.ink4 } else { Color32::WHITE });
810:         } else {
811:             self.label_button(ui, r, None, &cf.ok, "cf-ok-draw", Btn::Accent);
812:         }
813:         if resp.clicked() && can_proceed {
814:             acts.push((*cf.act).clone());
815:             *close = false;
816:             acts.push(Act::CloseModal);
817:             self.confirm_input.clear();
818:         }
