249:     pub mod adb {
250:         use super::*;
251:         use crate::model::Entry;
252:         use crate::vfs::*;
253:         use std::io::{Read, Write};
254:         use std::process::Stdio;
255: 
256:         pub fn adb_available() -> bool {
257:             Command::new("adb").arg("version").output().map(|o| o.status.success()).unwrap_or(false)
258:         }
