357:                 let Ok(out) = run("adb", &["devices", "-l"]) else { return vec![] };
358:                 let mut v = vec![];
359:                 for l in out.lines().skip(1) {
360:                     let parts: Vec<&str> = l.split_whitespace().collect();
361:                     if parts.len() < 2 {
362:                         continue;
363:                     }
364:                     let serial = parts[0].to_string();
365:                     let state = parts[1].to_string();
366:                     if state == "device-list" || serial == "List" {
367:                         continue;
368:                     }
369:                     let model = l.split_whitespace().find_map(|p| p.strip_prefix("model:")).unwrap_or("Android").replace('_', " ");
370:                     v.push((serial, model, state));
371:                 }
372:                 v
373:             }
374:         }
375:         impl DeviceProvider for AdbDevices {
376:             fn list(&self) -> Vec<Device> {
377:                 self.query()
378:                     .into_iter()
379:                     .map(|(serial, model, state)| {
380:                         let authorized = state == "device";
381:                         let detail = match state.as_str() {
382:                             "device" => "Android · ADB".into(),
383:                             "unauthorized" => "Authorization required — tap Allow USB debugging on the phone".into(),
384:                             "offline" => "Offline — reconnect the phone".into(),
385:                             other => format!("Android · ADB ({})", other),
386:                         };
387:                         let battery = if authorized {
388:                             run("adb", &["-s", &serial, "shell", "dumpsys battery | grep level"]).ok().and_then(|s| s.split(':').nth(1).and_then(|n| n.trim().parse().ok()))
389:                         } else {
390:                             None
391:                         };
392:                         Device { id: format!("adb:{}", serial), name: model, kind: DeviceKind::Phone, detail, mounted: authorized, loc: if authorized { Some(Location::new(format!("adb:{}", serial), "/sdcard")) } else { None }, total: 0, free: 0, fs_type: "adb".into(), can_unmount: false, can_eject: false, battery }
393:                     })
394:                     .collect()
395:             }
396:             fn mount(&self, id: &str) -> Result<Mounted, String> {
397:                 let serial = id.trim_start_matches("adb:");
398:                 Ok(Mounted { loc: Location::new(id, "/sdcard"), vfs: Some(Arc::new(AdbVfs::new(serial))) })
399:             }
400:             fn unmount(&self, _id: &str) -> Result<(), String> {
401:                 Err("Disconnect the phone to unmount".into())
402:             }
403:             fn owns(&self, id: &str) -> bool {
404:                 id.starts_with("adb:")
405:             }
406:         }
